//! Bounded navigation requests. Queuing does not confirm that a UI showed them.
use super::*;
use std::collections::BTreeSet;
const MAX_PENDING:usize=8;
const MAX_ACKNOWLEDGED:usize=32;
const MAX_BYTES:usize=512*1024;
fn conflict(message:&str)->Error{let mut error=Error::new(message);error.status=409;error}
fn exact(repo:&Repository,value:&str)->Result<()>{let mut projected=value.to_owned();commands::redact_text(repo,&mut projected);if projected!=value{return Err(Error::new("Presentation identity is unavailable for safe projection."));}Ok(())}
fn identity(repo:&Repository,value:&Value,max:usize)->Result<String>{let value=value.as_str().filter(|value|!value.is_empty()&&value.chars().count()<=max&&!value.chars().any(char::is_control)).ok_or(Error::new("Supply an exact bounded presentation identity."))?;exact(repo,value)?;Ok(value.into())}
fn request(repo:&Repository,value:&Value)->Result<String>{let value=identity(repo,value,36)?;if sid(&value)?!=value{return Err(Error::new("Supply a canonical presentation request UUID."));}Ok(value)}
fn vocabulary(repo:&Repository)->Result<()>{for value in ["queued","shown","dismissed","saved-view","display-items","work","chat"]{exact(repo,value)?;}Ok(())}
fn clipped(repo:&Repository,value:&Value,max:usize)->Value{let mut value=value.as_str().unwrap_or("").to_owned();commands::redact_text(repo,&mut value);json!(value.chars().take(max).collect::<String>())}
fn work(repo:&Repository,item:&Value)->Result<Value>{
 let projected=work_search::project(item,usize::MAX);let item=&projected;
 let mut result=json!({"id":identity(repo,&item["id"],160)?});
 for field in ["title","reference","url","project","sourceStatus","detail"]{if item[field].is_string(){result[field]=clipped(repo,&item[field],if field=="url"{4096}else{300});}}
 for field in ["source","kind","status","sourceStatusCode"]{if item[field].is_string(){result[field]=json!(identity(repo,&item[field],80)?);}}
 if item["projectId"].is_string(){result["projectId"]=json!(identity(repo,&item["projectId"],160)?);}
 for field in ["pinned","hidden","snoozed","overridden","sourceUnavailable"]{if let Some(value)=item[field].as_bool(){result[field]=json!(value);}}
 for field in ["createdAt","updatedAt","archivedAt"]{if let Some(value)=item[field].as_f64().filter(|value|value.is_finite()&&*value>=0.0){result[field]=json!(value);}else if item[field].is_string(){result[field]=clipped(repo,&item[field],80);}}
 if let Some(reasons)=item["actionReasons"].as_array(){result["actionReasons"]=json!(reasons.iter().take(20).map(|value|clipped(repo,value,300)).collect::<Vec<_>>());}
 if item["parent"].is_object(){result["parent"]=parent(repo,&item["parent"],0)?;}
 if let Some(relations)=item["relations"].as_array(){result["relations"]=json!(relations.iter().take(100).filter_map(Value::as_str).map(|value|{let mut value=value.to_owned();commands::redact_text(repo,&mut value);value.chars().take(160).collect::<String>()}).collect::<Vec<_>>());}
 if item["ci"].is_object(){let mut ci=json!({});if item["ci"]["state"].is_string(){ci["state"]=json!(identity(repo,&item["ci"]["state"],40)?);}if item["ci"]["summary"].is_string(){ci["summary"]=clipped(repo,&item["ci"]["summary"],300);}for field in ["total","passed","failed","pending","skipped"]{if let Some(count)=item["ci"][field].as_u64(){ci[field]=json!(count.min(1000000));}}if let Some(checks)=item["ci"]["checks"].as_array(){ci["checks"]=json!(checks.iter().take(100).map(|check|{let mut result=json!({});for field in ["name","state","url","workflow"]{if check[field].is_string(){result[field]=clipped(repo,&check[field],if field=="url"{4096}else{300});}}result}).collect::<Vec<_>>());}result["ci"]=ci;}
 Ok(result)
}
fn parent(repo:&Repository,item:&Value,depth:usize)->Result<Value>{let mut result=json!({"id":identity(repo,&item["id"],160)?});for field in ["title","reference","url"]{if item[field].is_string(){result[field]=clipped(repo,&item[field],if field=="url"{4096}else{300});}}if depth<4&&item["parent"].is_object(){result["parent"]=parent(repo,&item["parent"],depth+1)?;}Ok(result)}
fn chat(repo:&Repository,item:&Value)->Result<Value>{let mut result=json!({"id":identity(repo,&item["id"],160)?,"title":clipped(repo,&item["title"],300),"agent":identity(repo,&item["agent"],30)?,"cwd":clipped(repo,&item["cwd"],4096),"archived":item["archived"]==true,"live":item["live"]==true});result["items"]=json!(arr(&item["items"]).iter().take(100).map(|item|work(repo,item)).collect::<Result<Vec<_>>>()?);Ok(result)}
/// Shared immediate App chat and queued external presentation builders.
pub(super) fn saved_view(repo:&Repository,args:&Value)->Result<Value>{let id=identity(repo,&args["id"],80)?;let doc=views::load(repo)?;let view=doc.views.iter().find(|view|view.id==id).ok_or(Error::new("Saved view unavailable. Read views.read first."))?;Ok(json!({"type":"saved-view","id":id,"name":clipped(repo,&json!(view.name),120)}))}
pub(super) fn display_items(repo:&Repository,args:&Value)->Result<Value>{
 let items=args["items"].as_array().filter(|items|!items.is_empty()&&items.len()<=40).ok_or(Error::new("Supply 1 to 40 exact item targets."))?;
 let catalog={let state=repo.state.lock().map_err(|_|Error::io())?;domain::catalog(&state).into_iter().map(|(id,item)|(id,work_search::effective(&state,&item))).collect::<std::collections::BTreeMap<_,_>>()};
 let mut rows=vec![];let mut keys=BTreeSet::new();
 for target in items{let id=identity(repo,&target["id"],160)?;let kind=text(target,"type");let item=match kind{"work"=>work(repo,catalog.get(&id).ok_or(Error::new("A work item is no longer cached. Search again."))?)?,"chat"=>chat(repo,&chat_search::target(repo,&id)?)?,_=>return Err(Error::new("Choose a work or chat target."))};if keys.insert(format!("{kind}:{id}")){rows.push(json!({"type":kind,"id":id,"item":item}));}}
 let recommended=match args.get("recommended").filter(|value|!value.is_null()){Some(value)=>{let id=identity(repo,&value["id"],160)?;let kind=text(value,"type");if !rows.iter().any(|row|row["type"]==kind&&row["id"]==id){return Err(Error::new("The recommendation must be one of the displayed targets."));}json!({"type":kind,"id":id})},None=>Value::Null};
 Ok(json!({"type":"display-items","title":clipped(repo,&json!(checked(args,"title",120,false)?),120),"items":rows,"recommended":recommended,"reason":clipped(repo,&json!(checked(args,"reason",300,false)?),300)}))
}
fn canonical(repo:&Repository,args:&Value)->Result<Value>{match text(args,"type"){"saved-view"=>saved_view(repo,args),"display-items"=>display_items(repo,args),_=>Err(Error::new("Unknown presentation type."))}}
fn empty()->Value{json!({"version":1,"entries":[]})}
fn entries(document:&Value)->Result<Vec<Value>>{
 if document.is_null(){return Ok(vec![]);}if document["version"]!=1{return Err(Error::new("Unsupported presentation state version."));}
 if serde_json::to_vec(document)?.len()>MAX_BYTES{return Err(Error::new("Presentation state exceeds its supported limit."));}
 let rows=document["entries"].as_array().filter(|rows|rows.len()<=MAX_PENDING+MAX_ACKNOWLEDGED).ok_or(Error::new("Invalid presentation state."))?;let mut seen=BTreeSet::new();let mut pending=0;
 for row in rows{let id=text(row,"requestId");if sid(id).is_err()||sid(id)?!=id||!seen.insert(id)||!row["hash"].as_str().is_some_and(|hash|hash.len()==64&&hash.bytes().all(|byte|byte.is_ascii_hexdigit()))||!matches!(text(row,"status"),"queued"|"shown"|"dismissed"){return Err(Error::new("Invalid presentation state."));}if row["status"]=="queued"{pending+=1;if !row["presentation"].is_object(){return Err(Error::new("Invalid queued presentation."));}}}
 if pending>MAX_PENDING||rows.len()-pending>MAX_ACKNOWLEDGED{return Err(Error::new("Presentation state exceeds its supported limit."));}Ok(rows.clone())
}
fn receipt(repo:&Repository,row:&Value)->Result<Value>{let id=request(repo,&row["requestId"])?;exact(repo,text(row,"status"))?;Ok(json!({"requestId":id,"status":row["status"]}))}
fn stored_descriptor(repo:&Repository,value:&Value)->Result<Value>{match text(value,"type"){
 "saved-view"=>Ok(json!({"type":"saved-view","id":identity(repo,&value["id"],80)?,"name":clipped(repo,&value["name"],120)})),
 "display-items"=>{let rows=value["items"].as_array().filter(|rows|!rows.is_empty()&&rows.len()<=40).ok_or(Error::new("Invalid queued presentation."))?;let mut items=vec![];for row in rows{let id=identity(repo,&row["id"],160)?;if row["item"]["id"]!=id{return Err(Error::new("Invalid queued presentation identity."));}let kind=text(row,"type");let item=match kind{"work"=>work(repo,&row["item"])? ,"chat"=>chat(repo,&row["item"])? ,_=>return Err(Error::new("Invalid queued presentation type."))};items.push(json!({"type":kind,"id":id,"item":item}));}let recommended=&value["recommended"];if !recommended.is_null()&&!items.iter().any(|row|row["type"]==recommended["type"]&&row["id"]==recommended["id"]){return Err(Error::new("Invalid queued recommendation."));}Ok(json!({"type":"display-items","title":clipped(repo,&value["title"],120),"items":items,"recommended":if recommended.is_null(){Value::Null}else{json!({"type":recommended["type"],"id":recommended["id"]})},"reason":clipped(repo,&value["reason"],300)}))},_=>Err(Error::new("Invalid queued presentation type."))}}
pub(super) fn present(repo:&Repository,args:&Value)->Result<Value>{
 commands::validate_presentation_arguments("present",args)?;vocabulary(repo)?;let id=request(repo,&args["requestId"])?;let hash=context_kit::sha256(&serde_json::to_vec(&args["presentation"])?);
 {let state=repo.state.lock().map_err(|_|Error::io())?;let rows=entries(&state["uiPresentations"])?;if let Some(row)=rows.iter().find(|row|row["requestId"]==id){if row["hash"]!=hash{return Err(conflict("This presentation request ID already has different content."));}return receipt(repo,row);}if rows.iter().filter(|row|row["status"]=="queued").count()>=MAX_PENDING{return Err(conflict("Eight presentation requests are awaiting review. Show or dismiss one before queuing another."));}}
 let descriptor=canonical(repo,&args["presentation"])?;
 repo.transaction_if_changed(|state|{let mut rows=entries(&state["uiPresentations"])?;if let Some(row)=rows.iter().find(|row|row["requestId"]==id){if row["hash"]!=hash{return Err(conflict("This presentation request ID already has different content."));}return receipt(repo,row);}if rows.iter().filter(|row|row["status"]=="queued").count()>=MAX_PENDING{return Err(conflict("Eight presentation requests are awaiting review. Show or dismiss one before queuing another."));}let row=json!({"requestId":id,"hash":hash,"status":"queued","presentation":descriptor});let result=receipt(repo,&row)?;rows.push(row);if state["uiPresentations"].is_null(){state["uiPresentations"]=empty();}state["uiPresentations"]["entries"]=json!(rows);entries(&state["uiPresentations"])?;Ok(result)})
}
pub(super) fn read(repo:&Repository)->Result<Value>{vocabulary(repo)?;let rows={let state=repo.state.lock().map_err(|_|Error::io())?;entries(&state["uiPresentations"])?};let mut pending=vec![];let mut receipts=vec![];for row in rows{receipts.push(receipt(repo,&row)?);if row["status"]=="queued"{pending.push(json!({"requestId":request(repo,&row["requestId"])?,"presentation":stored_descriptor(repo,&row["presentation"])?}));}}Ok(json!({"pending":pending,"receipts":receipts}))}
pub(super) fn acknowledge(repo:&Repository,args:&Value)->Result<Value>{commands::validate_presentation_arguments("ack",args)?;vocabulary(repo)?;let id=request(repo,&args["requestId"])?;let outcome=text(args,"outcome");repo.transaction_if_changed(|state|{let mut rows=entries(&state["uiPresentations"])?;let row=rows.iter_mut().find(|row|row["requestId"]==id).ok_or(conflict("This presentation request is unavailable or its receipt has expired."))?;if row["status"]!="queued"{if row["status"]!=outcome{return Err(conflict("This presentation request already has a different acknowledgment."));}return receipt(repo,row);}row["status"]=json!(outcome);row.as_object_mut().unwrap().remove("presentation");let result=receipt(repo,row)?;while rows.iter().filter(|row|row["status"]!="queued").count()>MAX_ACKNOWLEDGED{let index=rows.iter().position(|row|row["status"]!="queued").unwrap();rows.remove(index);}state["uiPresentations"]["entries"]=json!(rows);Ok(result)})}

#[cfg(test)]
mod tests{
 use super::*;use std::sync::Arc;
 fn fixture()->(tempfile::TempDir,Arc<Repository>){fixture_secret(None)}
 fn fixture_secret(secret:Option<&str>)->(tempfile::TempDir,Arc<Repository>){let temp=tempfile::tempdir().unwrap();if let Some(secret)=secret{std::fs::write(temp.path().join(".env"),format!("MYDASH_PRESENTATION_SECRET={secret}\n")).unwrap();}let repo=Repository::open(temp.path().into(),None,true).unwrap();repo.transaction(|state|{state["items"]=json!([{"id":"linear:a","source":"linear","kind":"Issue","title":"Cached work","status":"todo","detail":"Details","privateExtension":"PRIVATE_WORK","ci":{"state":"failed","total":7,"passed":5,"failed":2,"privateExtension":"PRIVATE_CI"}}]);state["sessions"]=json!([{"id":"10000000-0000-4000-8000-000000000001","agent":"codex","title":"Saved chat","cwd":"/safe/reference","items":[{"id":"linear:a","title":"Linked","privateExtension":"PRIVATE_LINK"}],"privateExtension":"PRIVATE_CHAT"}]);Ok(())}).unwrap();(temp,repo)}
 fn args(id:&str)->Value{json!({"requestId":id,"presentation":{"type":"display-items","title":"Chosen results","items":[{"type":"work","id":"linear:a"},{"type":"chat","id":"10000000-0000-4000-8000-000000000001"}],"recommended":{"type":"work","id":"linear:a"},"reason":"Verified cached matches"}})}
 #[test]fn presentation_canonical_builder_is_shared_bounded_and_strips_private_extensions(){let (_temp,repo)=fixture();let args=args(&uuid());let expected=display_items(&repo,&args["presentation"]).unwrap();let receipt=present(&repo,&args).unwrap();assert_eq!(receipt,json!({"requestId":args["requestId"],"status":"queued"}));let result=read(&repo).unwrap();assert_eq!(result["pending"][0]["presentation"],expected);for marker in ["PRIVATE_WORK","PRIVATE_CHAT","PRIVATE_LINK","PRIVATE_CI","hash"]{assert!(!result.to_string().contains(marker));}assert_eq!(result["pending"][0]["presentation"]["items"][0]["item"]["ci"]["state"],"failed");assert_eq!(result["pending"][0]["presentation"]["items"][0]["item"]["ci"]["total"],7);assert_eq!(result["pending"][0]["presentation"]["items"][1]["item"]["items"][0]["title"],"Linked");assert!(repo.embedded.inventory().is_empty());assert!(repo.cooldown.lock().unwrap().is_empty());}
 #[test]fn presentation_replay_precedes_catalog_resolution_and_conflicts_before_mutation(){let (_temp,repo)=fixture();let args=args(&uuid());let first=present(&repo,&args).unwrap();repo.transaction(|state|{state["items"]=json!([]);state["sessions"]=json!([]);Ok(())}).unwrap();let before=std::fs::read(&repo.data).unwrap();assert_eq!(present(&repo,&args).unwrap(),first);assert_eq!(std::fs::read(&repo.data).unwrap(),before);let mut changed=args.clone();changed["presentation"]["title"]=json!("Other intent");assert_eq!(present(&repo,&changed).unwrap_err().status,409);assert_eq!(std::fs::read(&repo.data).unwrap(),before);}
 #[test]fn presentation_ack_is_exact_and_releases_only_its_pending_descriptor(){let (_temp,repo)=fixture();let first=args(&uuid());let second=args(&uuid());present(&repo,&first).unwrap();present(&repo,&second).unwrap();repo.transaction(|state|{state["uiPresentations"]["extension"] = json!({"private":"ROOT_PRIVATE"});state["uiPresentations"]["entries"][0]["extension"]=json!("ENTRY_PRIVATE");Ok(())}).unwrap();let ack=json!({"requestId":first["requestId"],"outcome":"shown"});assert_eq!(acknowledge(&repo,&ack).unwrap()["status"],"shown");let before=std::fs::read(&repo.data).unwrap();assert_eq!(acknowledge(&repo,&ack).unwrap()["status"],"shown");assert_eq!(std::fs::read(&repo.data).unwrap(),before);assert_eq!(acknowledge(&repo,&json!({"requestId":first["requestId"],"outcome":"dismissed"})).unwrap_err().status,409);assert_eq!(acknowledge(&repo,&json!({"requestId":uuid(),"outcome":"shown"})).unwrap_err().status,409);let result=read(&repo).unwrap();assert_eq!(result["pending"].as_array().unwrap().len(),1);assert_eq!(result["pending"][0]["requestId"],second["requestId"]);assert!(!result.to_string().contains("PRIVATE"));let state=repo.state.lock().unwrap();assert_eq!(state["uiPresentations"]["extension"]["private"],"ROOT_PRIVATE");assert_eq!(state["uiPresentations"]["entries"][0]["extension"],"ENTRY_PRIVATE");assert!(state["uiPresentations"]["entries"][0].get("presentation").is_none());}
 #[test]fn presentation_pending_capacity_never_evicts_and_acknowledged_retention_is_bounded(){let (_temp,repo)=fixture();let mut requests=vec![];for _ in 0..8{let args=args(&uuid());present(&repo,&args).unwrap();requests.push(args);}let before=std::fs::read(&repo.data).unwrap();assert_eq!(present(&repo,&args(&uuid())).unwrap_err().status,409);assert_eq!(present(&repo,&requests[0]).unwrap()["status"],"queued");assert_eq!(std::fs::read(&repo.data).unwrap(),before);for index in 0..40{let request_id=if index<7{requests[index]["requestId"].as_str().unwrap().to_owned()}else{let next=args(&uuid());present(&repo,&next).unwrap();next["requestId"].as_str().unwrap().to_owned()};acknowledge(&repo,&json!({"requestId":request_id,"outcome":"dismissed"})).unwrap();}let result=read(&repo).unwrap();assert_eq!(result["pending"].as_array().unwrap().len(),1);assert_eq!(result["pending"][0]["requestId"],requests[7]["requestId"]);assert_eq!(result["receipts"].as_array().unwrap().len(),33);assert_eq!(acknowledge(&repo,&json!({"requestId":requests[0]["requestId"],"outcome":"shown"})).unwrap_err().status,409);}
 #[test]fn presentation_invalid_versions_targets_and_arguments_fail_without_writes(){let (_temp,repo)=fixture();let before=std::fs::read(&repo.data).unwrap();for value in [json!({"requestId":uuid(),"presentation":{"type":"display-items","items":[{"type":"work","id":"missing"}]}}),json!({"requestId":uuid(),"presentation":{"type":"display-items","items":[{"type":"work","id":"linear:a","private":"not accepted"}]}}),json!({"requestId":uuid(),"presentation":{"type":"script","code":"not executable"}}),json!({"requestId":uuid(),"presentation":{"type":"display-items","items":vec![json!({"type":"work","id":"linear:a"});41]}})]{assert!(present(&repo,&value).is_err());assert_eq!(std::fs::read(&repo.data).unwrap(),before);}repo.transaction(|state|{state["uiPresentations"]=json!({"version":2,"entries":[]});Ok(())}).unwrap();let before=std::fs::read(&repo.data).unwrap();assert!(read(&repo).is_err());assert!(present(&repo,&args(&uuid())).is_err());assert!(acknowledge(&repo,&json!({"requestId":uuid(),"outcome":"shown"})).is_err());assert_eq!(std::fs::read(&repo.data).unwrap(),before);}
 #[test]fn presentation_failed_save_and_concurrent_same_request_have_one_canonical_entry(){let (_temp,repo)=fixture();let args=args(&uuid());let before=repo.state.lock().unwrap().clone();let bytes=std::fs::read(&repo.data).unwrap();std::fs::create_dir(repo.data.with_extension("tmp")).unwrap();assert!(present(&repo,&args).is_err());assert_eq!(*repo.state.lock().unwrap(),before);assert_eq!(std::fs::read(&repo.data).unwrap(),bytes);std::fs::remove_dir(repo.data.with_extension("tmp")).unwrap();let threads=(0..4).map(|_|{let repo=repo.clone();let args=args.clone();std::thread::spawn(move||present(&repo,&args).unwrap())}).collect::<Vec<_>>();for thread in threads{assert_eq!(thread.join().unwrap()["status"],"queued");}assert_eq!(read(&repo).unwrap()["pending"].as_array().unwrap().len(),1);}
 #[test]fn presentation_saved_view_is_resolved_canonically_and_not_created_by_read(){let (_temp,repo)=fixture();let doc=views::load(&repo).unwrap();let view=doc.views.first().unwrap();let args=json!({"requestId":uuid(),"presentation":{"type":"saved-view","id":view.id}});let before=std::fs::read(&repo.data).unwrap();assert_eq!(read(&repo).unwrap(),json!({"pending":[],"receipts":[]}));assert_eq!(std::fs::read(&repo.data).unwrap(),before);present(&repo,&args).unwrap();assert_eq!(read(&repo).unwrap()["pending"][0]["presentation"],saved_view(&repo,&args["presentation"]).unwrap());}
 #[test]fn presentation_routing_tags_are_exact_or_fail_before_queue_and_on_read(){for secret in ["linear","Issue","todo","codex","failed"]{let (_temp,repo)=fixture_secret(Some(secret));let before=std::fs::read(&repo.data).unwrap();assert!(present(&repo,&args(&uuid())).is_err(),"{secret}");assert_eq!(std::fs::read(&repo.data).unwrap(),before);}let (temp,repo)=fixture();present(&repo,&args(&uuid())).unwrap();std::fs::write(temp.path().join(".env"),"MYDASH_PRESENTATION_SECRET=linear\n").unwrap();drop(repo);let repo=Repository::open(temp.path().into(),None,true).unwrap();let before=std::fs::read(&repo.data).unwrap();assert!(read(&repo).is_err());assert_eq!(std::fs::read(&repo.data).unwrap(),before);}
 #[test]fn presentation_redacts_complete_display_values_before_truncation(){let secret=format!("private-display-{}","Z".repeat(350));let (_temp,repo)=fixture_secret(Some(&secret));repo.transaction(|state|{state["items"][0]["detail"]=json!(format!("{secret} visible"));Ok(())}).unwrap();let value=display_items(&repo,&args(&uuid())["presentation"]).unwrap();assert_eq!(value["items"][0]["item"]["detail"],"[redacted] visible");assert!(!value.to_string().contains("private-display-"));}

}
